// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "i changed my mind move the previous pane and this one into separate "overview" tab"
// Changes: Prehľad (overview) tab – the formal G = (N, T, P, S) and the symbol table, moved out of the Definition tab.

import { useMemo } from 'react'
import type { Grammar } from '#/lib/analysis'
import { fmtSet, ruleText } from '#/lib/grammar'
import { ListTable, Panel } from './ui'
import { SplitLayout } from './SplitLayout'

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: Shows the analysed grammar from the grammar module instead of deciding N, T and S again.
export function OverviewTab({ grammar: g }: { grammar: Grammar }) {

  const counts = useMemo(() => {
    const lhs = new Map<string, number>()
    const rhs = new Map<string, number>()
    g.rules.forEach((r) => {
      lhs.set(r.lhs, (lhs.get(r.lhs) ?? 0) + 1)
      r.rhs.forEach((s) => rhs.set(s, (rhs.get(s) ?? 0) + 1))
    })
    return { lhs, rhs }
  }, [g.rules])

  return (
    <SplitLayout id="overview">
      <div className="min-w-0">
        <Panel title="G = (N, T, P, S)">
          <dl className="grid grid-cols-[auto_minmax(0,1fr)] gap-x-3 gap-y-1.5 font-mono text-[13px]">
            <dt className="text-zinc-500">N =</dt>
            <dd className="break-words text-zinc-200">{fmtSet(g.N)}</dd>
            <dt className="text-zinc-500">T =</dt>
            <dd className="break-words text-zinc-200">{fmtSet(g.T)}</dd>
            <dt className="text-zinc-500">S =</dt>
            <dd className="text-zinc-200">{g.S || '–'}</dd>
            <dt className="text-zinc-500">P =</dt>
            <dd className="text-zinc-200">{g.rules.length ? `{ ${g.rules.length} pravidiel }` : '∅'}</dd>
          </dl>
          {g.rules.length > 0 && (
            <ol className="mt-3 list-decimal pl-9 font-mono text-[13px] text-zinc-300 marker:text-zinc-500">
              {g.rules.map((r, i) => (
                <li key={i}>{ruleText(r)}</li>
              ))}
            </ol>
          )}
          {!g.declared && <div className="mt-3 text-xs text-zinc-500">N a T sú odvodené z pravidiel.</div>}
        </Panel>
      </div>

      <div className="min-w-0">
        <Panel title="Symboly">
          {g.N.length > 0 || g.T.length > 0 ? (
            <ListTable head={['Symbol', 'Druh', 'Pravidlá (A → …)', 'Výskyty v x', 'Popis']}>
              {[...g.N.map((s) => ({ s, kind: 'N' })), ...g.T.map((s) => ({ s, kind: 'T' }))].map(({ s, kind }) => (
                <tr key={kind + s}>
                  <td>
                    {s}
                    {s === g.S && <span className="ml-2 rounded bg-indigo-500/20 px-1.5 text-[11px] text-indigo-200">S</span>}
                  </td>
                  <td className={kind === 'N' ? 'text-sky-300' : 'text-amber-300'}>{kind === 'N' ? 'neterminál' : 'terminál'}</td>
                  <td>{counts.lhs.get(s) ?? 0}</td>
                  <td>{counts.rhs.get(s) ?? 0}</td>
                  <td className="font-sans whitespace-normal! text-zinc-400">{g.notes.get(s) ?? ''}</td>
                </tr>
              ))}
            </ListTable>
          ) : (
            <div className="text-sm text-zinc-500">Zatiaľ žiadne symboly – definuj gramatiku v záložke Definícia.</div>
          )}
        </Panel>
      </div>
    </SplitLayout>
  )
}
